                "content": "\"\"\"GENERATED by tools/src/projection/providers/python/execution-projection-provider.ts — do not hand-edit.\n\nThe canonical execution vector, mechanically:\nadmit-input -> resolve-event-authority -> execute-event-authority ->\nadmit-outcome -> resolve-disposition.\nSee kernel/contracts/execution/scenario-kernel-execution-vector.json.\nEach step, on completing or on the failure that ends the run early,\nemits exactly one scenario-execution-observation.v1 via the injected\nExecutionObserver — see\nkernel/schemas/scenario-execution-observation.schema.json and governance\nrules K011-K013.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport asyncio\n\nfrom datetime import datetime, timezone\n\nfrom ..contracts import Scenario, ScenarioExecution\nfrom .execution_ports import (\n    ContractAdmissionError,\n    ContractValidator,\n    DispositionResolver,\n    ExecuteOptions,\n    ExecutionAuthorityResolver,\n    ExecutionObserver,\n    ExecutionStepObservation,\n    SemanticExecutor,\n)\n\n\nclass ScenarioKernel:\n    def __init__(\n        self,\n        contracts: ContractValidator,\n        authority_resolver: ExecutionAuthorityResolver,\n        executor: SemanticExecutor,\n        dispositions: DispositionResolver,\n        observer: ExecutionObserver,\n    ) -> None:\n        self._contracts = contracts\n        self._authority_resolver = authority_resolver\n        self._executor = executor\n        self._dispositions = dispositions\n        self._observer = observer\n\n    async def execute(self, scenario: Scenario, options: ExecuteOptions) -> ScenarioExecution:\n        contracts = self._contracts\n        authority_resolver = self._authority_resolver\n        executor = self._executor\n        dispositions = self._dispositions\n        observer = self._observer\n\n        def observe(step_id: str, sequence: int, status: str) -> None:\n            observer.observe(\n                ExecutionStepObservation(\n                    execution_id=options.execution_id,\n                    root_execution_id=options.root_execution_id,\n                    parent_execution_id=options.parent_execution_id,\n                    scenario_id=scenario.scenario_id,\n                    step_id=step_id,\n                    sequence=sequence,\n                    status=status,\n                    observed_at=datetime.now(timezone.utc).isoformat(),\n                )\n            )\n\n        try:\n            # admit-input\n            admitted_input = await contracts.admit(scenario.input.contract, options.input)\n            observe(\"admit-input\", 0, \"observed\")\n        except asyncio.CancelledError:\n            raise\n        except ContractAdmissionError:\n            observe(\"admit-input\", 0, \"admission-rejected\")\n            return ScenarioExecution(\n                execution_id=options.execution_id,\n                scenario_id=scenario.scenario_id,\n                root_execution_id=options.root_execution_id,\n                parent_execution_id=options.parent_execution_id,\n                input=options.input,\n                event=scenario.event,\n                outcome=None,\n                disposition=\"rejected\",\n            )\n\n        # resolve-event-authority\n        authority = await authority_resolver.resolve(scenario.event)\n        observe(\"resolve-event-authority\", 1, \"observed\")\n\n        try:\n            # execute-event-authority\n            candidate_outcome = await executor.execute(authority, admitted_input)\n            observe(\"execute-event-authority\", 2, \"observed\")\n        except asyncio.CancelledError:\n            raise\n        except Exception:\n            observe(\"execute-event-authority\", 2, \"execution-failed\")\n            return ScenarioExecution(\n                execution_id=options.execution_id,\n                scenario_id=scenario.scenario_id,\n                root_execution_id=options.root_execution_id,\n                parent_execution_id=options.parent_execution_id,\n                input=admitted_input,\n                event=scenario.event,\n                outcome=None,\n                disposition=\"failed\",\n            )\n\n        try:\n            # admit-outcome\n            admitted_outcome = await contracts.admit(scenario.outcome.contract, candidate_outcome)\n            observe(\"admit-outcome\", 3, \"observed\")\n        except asyncio.CancelledError:\n            raise\n        except ContractAdmissionError:\n            observe(\"admit-outcome\", 3, \"admission-rejected\")\n            return ScenarioExecution(\n                execution_id=options.execution_id,\n                scenario_id=scenario.scenario_id,\n                root_execution_id=options.root_execution_id,\n                parent_execution_id=options.parent_execution_id,\n                input=admitted_input,\n                event=scenario.event,\n                outcome=candidate_outcome,\n                disposition=\"rejected\",\n            )\n\n        # resolve-disposition\n        disposition = dispositions.resolve(scenario, admitted_outcome)\n        observe(\"resolve-disposition\", 4, \"observed\")\n\n        return ScenarioExecution(\n            execution_id=options.execution_id,\n            scenario_id=scenario.scenario_id,\n            root_execution_id=options.root_execution_id,\n            parent_execution_id=options.parent_execution_id,\n            input=admitted_input,\n            event=scenario.event,\n            outcome=admitted_outcome,\n            disposition=disposition,\n        )\n"
